
// Generated by Mark-LV Unity agent. Only active for projects carrying its marker.
using System;
using System.IO;
using System.Reflection;
using System.Threading.Tasks;
using UnityEditor;
using UnityEngine;
[InitializeOnLoad]
public static class MarkLVUnityBootstrap
{
    static readonly string Root = Path.GetFullPath(Path.Combine(Application.dataPath, ".."));
    static readonly string State = Path.Combine(Root, "Library", "MarkLVAgent", "mcp-state.txt");
    static readonly string Marker = Path.Combine(Root, "ProjectSettings", "MarkLV-MCP.json");
    static bool busy;
    static double retryAfter;
    static MarkLVUnityBootstrap() { EditorApplication.update += Tick; }
    static void Write(string value) { Directory.CreateDirectory(Path.GetDirectoryName(State)); File.WriteAllText(State, value); }
    static Type Find(string name) {
        foreach (var a in AppDomain.CurrentDomain.GetAssemblies()) { var t = a.GetType(name); if(t != null) return t; }
        throw new Exception("MCP package not loaded: " + name);
    }
    static object Service(string name) { return Find("MCPForUnity.Editor.Services.MCPServiceLocator").GetProperty(name).GetValue(null); }
    static object Call(object service, string method, params object[] args) { return service.GetType().GetMethod(method).Invoke(service, args); }
    static void Tick() {
        if (!File.Exists(Marker) || Application.isBatchMode || busy || EditorApplication.isCompiling || EditorApplication.isUpdating || EditorApplication.timeSinceStartup < retryAfter) return;
        busy = true; _ = Start();
    }
    static async Task Start() {
        try {
            EditorPrefs.SetBool("MCPForUnity.UseHttpTransport", true);
            EditorPrefs.SetString("MCPForUnity.HttpTransportScope", "local");
            EditorPrefs.SetString("MCPForUnity.HttpUrl", "http://127.0.0.1:8080");
            var cacheType = Find("MCPForUnity.Editor.Services.EditorConfigurationCache");
            var cache = cacheType.GetProperty("Instance").GetValue(null);
            Call(cache, "Refresh");
            Write("Starting local MCP server...");
            var server = Service("Server");
            if (!(bool)Call(server, "IsLocalHttpServerReachable")) {
                if (!(bool)Call(server, "StartLocalHttpServer", true)) throw new Exception("Server launch failed. Check Git, uv/Python and MCP settings in Unity.");
            }
            var deadline = DateTime.UtcNow.AddMinutes(5);
            while (!(bool)Call(server, "IsLocalHttpServerReachable")) {
                if (DateTime.UtcNow > deadline) throw new Exception("MCP server did not become reachable within five minutes.");
                await Task.Delay(500);
            }
            Write("Connecting Unity bridge...");
            if (!await (Task<bool>)Call(Service("Bridge"), "StartAsync")) throw new Exception("Unity bridge connection failed.");
            Write("READY");
            EditorApplication.update -= Tick;
        } catch(Exception ex) {
            Write("ERROR: " + (ex.InnerException ?? ex).Message);
            Debug.LogWarning("Mark-LV MCP setup: " + ex);
            retryAfter = EditorApplication.timeSinceStartup + 30;
        } finally { busy = false; }
    }
}
